"""Three sourced mock case stories, composed as a reversible paper-card deck."""
import json
from pathlib import Path
from html import escape as esc
B=Path(__file__).resolve().parent

def render_hero_deck():
 cars=json.loads((B/'dist/cars.json').read_text())['cars'];by_id={c['id']:c for c in cars}
 cases=[
 {'id':'swift','category':'Mileage','title':'This Swift has two different readings.','copy':'The last service invoice says 72,000 km. The seller declares 58,000 km. Ask to compare the original documents.','label':'Mileage to verify','value':'14,000','unit':'km','image':'swift-archive.webp','anchor':'mileage','short':'Swift'},
 {'id':'creta','category':'Finance','title':'This Creta needs a lender follow-up.','copy':'The lender entry is active and closure documents have not been provided. Check both before arranging a transfer.','label':'Lender entry','value':'Active','unit':'','image':'creta-archive.webp','anchor':'finance','short':'Creta'},
 {'id':'brezza','category':'Challans','title':'This Brezza has an unpaid entry.','copy':'An unpaid challan totals ₹1,500 in the records. Verify the current payment status with the seller.','label':'Unpaid challan','value':'₹1,500','unit':'','image':'brezza-archive.webp','anchor':'challans','short':'Brezza'}]
 # Facts are checked against the same report fixtures rather than invented for the animation.
 assert by_id['swift']['services'][-1]['km']-by_id['swift']['declaredKm']==14000
 assert by_id['creta']['lenderActive'] and not by_id['creta']['closureDocument']
 assert sum(r['amount'] for r in by_id['brezza']['challans'])==1500
 cards='''<article class="case-card case-overview" data-case="0"><div class="case-front"><div class="case-kicker"><span>Vehicle history report</span><span>Sample data</span></div><div class="overview-cars"><img src="assets/swift-archive.webp" width="900" height="600" alt="Maruti Suzuki Swift"><img src="assets/creta-archive.webp" width="900" height="600" alt="Hyundai Creta"><img src="assets/brezza-archive.webp" width="900" height="600" alt="Maruti Suzuki Brezza"></div><div class="case-identity"><h2>Know the history.<br>Ask a better question.</h2><p>Records. Photos. Next steps.</p></div><div class="overview-topics"><span>Identity &amp; ownership</span><span>Service &amp; mileage</span><span>Finance &amp; transfer</span></div><div class="case-mobile-detail"><p>See what to check, what is missing and what to ask the seller.</p></div></div></article>'''
 for i,item in enumerate(cases):
  c=by_id[item['id']];url=f'sample-{c["id"]}.html#{item["anchor"]}';item['url']=url;item['name']=c['name']
  cards+=f'''<article class="case-card" data-case="{i+1}"><div class="case-front"><div class="case-kicker"><span>Sample report · {item["category"]}</span><span>0{i+1} / {item['short']}</span></div><img class="case-art" src="assets/{item['image']}" width="900" height="600" alt="Blue ink illustration of a {c['year']} {esc(c['name'])} with archive papers"><div class="case-identity"><h2>{esc(c['name'])}</h2><p>{c['year']} · {esc(c['fuel'])} · {esc(c['transmission'])}</p></div><div class="case-finding"><span>{item['label']}</span><strong>{item['value']} <small>{item['unit']}</small></strong></div><div class="case-mobile-detail"><p>{item['copy']}</p><noscript><a href="{url}">View {item['short']}’s report</a></noscript></div></div></article>'''

 cases.insert(0,{'id':'overview','category':'Overview','title':'Know the history. Ask a better question.','name':'Vehicle history report','url':'#sample-reports','action':'Explore sample reports'})
 for item in cases[1:]:item['action']='View '+item['short']+'’s report'
 selectors=''.join(f'<button type="button" class="case-selector" aria-pressed="{str(i==0).lower()}" aria-label="Show {item["category"].lower()}">{item["category"]}</button>' for i,item in enumerate(cases))
 first=cases[0]
 html=f'''<div class="hero-stage"><div class="wrap minimal-hero case-hero-layout"><div class="hero-copy"><p class="eyebrow">VEHICLE HISTORY REPORTS</p><h1>A car’s past.<br>In black and <em>white.</em></h1><p class="hero-intro">Follow the available service, ownership and finance records. See what needs checking before you buy.</p><div class="hero-actions"><a class="button gold" href="#vehicle-check">Check your vehicle</a><a class="hero-secondary" href="#sample-reports">Explore sample reports</a></div></div><div class="case-deck-region" role="region" aria-roledescription="carousel" aria-label="Inside a vehicle history report"><div class="case-deck">{cards}</div><div class="case-deck-footer"><a id="case-report-action" class="button gold" href="{first['url']}">Explore sample reports</a><div class="case-playback"><span class="case-position" aria-hidden="true">01 / 04</span><button type="button" class="case-pause" aria-label="Pause car animation"><svg class="pause-icon" viewBox="0 0 20 20" aria-hidden="true"><path d="M7 5v10M13 5v10"/></svg><svg class="play-icon" viewBox="0 0 20 20" aria-hidden="true"><path d="m7 5 8 5-8 5Z"/></svg></button><button type="button" class="case-next" aria-label="Show next car"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m7 5 5 5-5 5"/></svg></button></div></div><div class="case-selectors" role="group" aria-label="Choose a report example">{selectors}</div><div class="case-progress" aria-hidden="true"><span></span></div><p class="visually-hidden" id="case-announcement" aria-live="polite"></p></div></div></div><script id="hero-case-data" type="application/json">{json.dumps(cases,ensure_ascii=False)}</script><noscript><style>.case-selectors,.case-playback,.case-progress,#case-report-action{{display:none}}.case-mobile-detail{{display:block!important}}</style></noscript>'''
 return html
